export const AR_MORE = { ...DATA, ...CHECK_EN_AR, ...UI };

// server sentences with values inside: [pattern, (match, translate) => Arabic]
export const PATTERNS = [
  [/^Risk (\S+) \(range (\S+) to (\S+)\)$/, (m) => `الخطورة ${m[1]} (النطاق ${m[2]} إلى ${m[3]})`],
  [/^day (\d+), (.+)$/, (m, T) => `اليوم ${m[1]}، ${T(m[2])}`],
  [/^(.+); support: (.+)$/, (m, T) => `${T(m[1])}؛ الدعم: ${T(m[2])}`],
  [/^(.+); family visit with (\S+)$/, (m, T) => `${T(m[1])}؛ زيارة عائلية مع ${m[2]}`],
  [/^(.+), evening slot$/, (m, T) => `${T(m[1])}، موعد مسائي`],
  [/^Mobile clinic on (\S+)$/, (m) => `عيادة متنقلة في ${m[1]}`],
  [/^(.+) to (guardian|person) in (\w+): (.*)$/, (m, T) => `${T(m[1])} إلى ${T(m[2])} باللغة ${T(m[3])}: ${T(m[4])}`],
  [/^(switch_channel|reminder_same_channel|community_health_worker) via (.+)$/, (m, T) => `${T(m[1])} عبر ${T(m[2])}`],
  [/^reminder day (\d+) via (.+)$/, (m, T) => `تذكير في اليوم ${m[1]} عبر ${T(m[2])}`],
  [/^invite again from day (\d+)$/, (m) => `دعوة مجددة من اليوم ${m[1]}`],
  [/^paused (\d+) days$/, (m) => `إيقاف مؤقت لمدة ${m[1]} أيام`],
  [/^(Urgent|High|Routine); (\d+) card\(s\)$/, (m, T) => `${T(m[1])}؛ ${m[2]} بطاقة`],
  [/^follow-up: (.+)$/, (m, T) => `متابعة: ${T(m[1])}`],
  [/^Urgent, no contact consent: (.+)$/, (m, T) => `عاجل، لا موافقة على التواصل: ${T(m[1])}`],
  [/^family opt-out \(STOP from (.+)\)$/, (m) => `انسحاب الأسرة (توقف من ${m[1]})`],
  [/^(.+) \(clinic's usual result handling\)$/, (m, T) => `${T(m[1])} (إجراءات العيادة المعتادة للنتائج)`],
  [/^Urgent but no contact consent, so no messages are sent; decide how to reach this person \(for example at their next visit\):\s*(.*)$/,
    (m, T) => `عاجل لكن دون موافقة على التواصل، لذا لا تُرسل رسائل؛ قرّر كيف يمكن الوصول إلى هذا الشخص (مثلاً في زيارته القادمة)${m[1] ? `: ${T(m[1])}` : ""}`],
  [/^Health talk in (\w+) with a trusted local leader$/, (m, T) => `محاضرة صحية باللغة ${T(m[1])} مع قائد محلي موثوق`],
  [/^(\d+) opt-outs today against ([\d.]+) a day last week: check the message wording and timing$/,
    (m) => `${m[1]} حالات انسحاب اليوم مقابل ${m[2]} يومياً الأسبوع الماضي: راجع صياغة الرسائل وتوقيتها`],
  [/^(\d+) Urgent people cannot be messaged \(no contact consent\): the clinician decides how to reach them, for example at their next visit$/,
    (m) => `لا يمكن مراسلة ${m[1]} من الحالات العاجلة (لا موافقة على التواصل): يقرر الطبيب كيفية الوصول إليهم، مثلاً في زيارتهم القادمة`],
  [/^(\d+) people past their contact deadline$/, (m) => `${m[1]} شخصاً تجاوزوا الموعد النهائي للتواصل`],
  [/^(age group|insurance|language|nationality|region|sex) (.+): (\S+) reached, against (\S+) for (.+)$/,
    (m, T) => `${T(m[1])} ${T(m[2])}: تم الوصول إلى ${m[3]}، مقابل ${m[4]} لـ ${T(m[5])}`],
  [/^Fairness gap \((.+), reached\)$/, (m, T) => `فجوة عدالة (${T(m[1])}، الوصول)`],
  [/^(Child|Adult), (\d+) y$/, (m, T) => `${T(m[1])}، ${m[2]} سنة`],
  [/^(\d+) y$/, (m) => `${m[1]} سنة`],
  [/^speaks (.+)$/, (m, T) => `يتحدث ${T(m[1])}`],
  [/^Record (\S+)$/, (m) => `السجل ${m[1]}`],
  [/^Genetic marker: (.+)$/, (m) => `مؤشر وراثي: ${m[1]}`],
  // the clinician summary (summaries.py): parts joined by "; ", then the standard last sentence
  [/^(.+)\. Priority for outreach, not a diagnosis\.$/, (m, T) => `${m[1].split("; ").map(T).join("؛ ")}. قائمة أولويات للتواصل، وليست تشخيصاً.`],
  [/^(Urgent|High|Routine|Flagged) because of the risk score$/, (m, T) => `${T(m[1])} بسبب درجة الخطورة`],
  [/^(Urgent|High|Routine|Flagged) because a routine check is due$/, (m, T) => `${T(m[1])} لأن فحصاً روتينياً مستحق`],
  [/^(Urgent|High|Routine|Flagged) because of (.+)$/, (m, T) => `${T(m[1])} بسبب ${T(m[2])}`],
  [/^risk score in the (\w+) band$/, (m, T) => `درجة الخطورة في الفئة: ${T(m[1])}`],
  [/^main factors: (.+)$/, (m, T) => `أهم العوامل: ${T(m[1])}`],
];
